"""The snapshot serializers keep the library version out of stored snapshots.

A stored version makes every snapshot holding it fail on the next version
bump, which first shows up in CI on the release commit itself.
"""

import re
from pathlib import Path

import pytest

from test.snapshot_serializers import (
    NormalisedHTMLSerializer,
    NormalisedMarkdownSerializer,
)

SNAPSHOTS = Path(__file__).parent / "__snapshots__"


@pytest.mark.parametrize(
    ("stamp", "expected"),
    [
        (
            "<!-- Generated by claude-code-log v1.7.1 -->",
            "<!-- Generated by claude-code-log v[VERSION] -->",
        ),
        (
            "<!-- Generated by claude-code-log v1.8.0 theme=minimal -->",
            "<!-- Generated by claude-code-log v[VERSION] theme=minimal -->",
        ),
        (
            "<!-- Generated by claude-code-log v1.8.0-dev -->",
            "<!-- Generated by claude-code-log v[VERSION] -->",
        ),
    ],
)
@pytest.mark.parametrize(
    "serializer", [NormalisedHTMLSerializer, NormalisedMarkdownSerializer]
)
def test_generator_stamp_loses_its_version(
    serializer: type[NormalisedHTMLSerializer] | type[NormalisedMarkdownSerializer],
    stamp: str,
    expected: str,
) -> None:
    assert serializer.serialize(f"{stamp}\n<p>x</p>\n") == f"{expected}\n<p>x</p>\n"


def test_no_stored_snapshot_holds_a_version() -> None:
    stored = sorted(SNAPSHOTS.glob("*.ambr"))
    assert stored
    found = [
        f"{path.name}: {match.group(0)}"
        for path in stored
        for match in re.finditer(
            r"Generated by claude-code-log v\d[^ >]*", path.read_text(encoding="utf-8")
        )
    ]
    assert found == []
